def fill2(g, color):
    H,W=g.shape
    canvas=np.zeros((H*2+1,W*2+1),bool)
    pts=list(zip(*np.where(g==color)))
    for r,c in pts: canvas[2*r,2*c]=1
    S=set(pts)
    for r,c in pts:
        for dr,dc in [(1,1),(1,-1)]:
            if (r+dr,c+dc) in S:
                canvas[2*r+1,2*c+dc]=1
    free=~canvas
    lab,n=label(free)
    border=set(lab[0])|set(lab[-1])|set(lab[:,0])|set(lab[:,-1])
    inside=free & ~np.isin(lab,list(border))
    out=g.copy()
    for r in range(H):
      for c in range(W):
       if out[r,c]==8 and inside[2*r,2*c]:out[r,c]=2
    return out
