def cone_fill(g,color):
 H,W=g.shape; out=g.copy()
 for r in range(H):
  for c in range(W):
   if g[r,c]!=8:continue
   ok=True
   for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
    rr,cc=r+dr,c+dc; found=False
    while 0<=rr<H and 0<=cc<W:
     if g[rr,cc]==color:found=True;break
     rr+=dr;cc+=dc
    if not found:ok=False;break
   if ok:out[r,c]=2
 return out
